", "t": [["terminal", "{"command":"cd \"D:/Projects/local_ai/strata-lab/runs/work/hermes/jsondiff-1794053379\" && python - <<'EOF'\nfrom jsondiff import diff\ncases = [\n    ([1], [True]),                      # bool vs int inside a list\n    ([1], [1.0]),                       # float vs int inside a list\n    (None, None), (None, False), (0, False), (\"\", None),\n    ({}, []),                           # dict vs list at root -> ~\n    ([], {}),\n    ({\"a\": {}}, {\"a\": {}}),\n    ([1, [2, {\"x\": [3]}]], [1, [2, {\"x\": [3, 4]}]]),\n    ({\"b\": 1, \"a\": 2}, {\"a\": 2, \"b\": 1}),   # key order irrelevant -> []\n    ([{\"a\": 1}], [{\"a\": 1}, {\"b\": 2}]),\n    ({\"deep\": {\"nested\": [1, 2]}}, {\"deep\": {\"nested\": [1, 2, {\"k\": None}]}}),\n]\nfor a, b in cases:\n    print(a, \"->\", b, \"=>\", diff(a, b))\n# determinism: sorting must not depend on set iteration order\nimport random\nd1 = {str(i): i for i in range(30)}\nd2 = {str(i): i + 1 for i in range(30) if i % 2}\nres = {tuple(diff(d1, d2)) for _ in range(20)}\nassert len(res) == 1, \"nondeterministic output\"\nprint(\"deterministic over 20 runs:\", sorted(res)[0][:2])\nEOF"}"]]}
